// src/Components/Navbar/Navbar.jsx
import React, { useState, useContext, useRef, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { AuthContext } from '../../context/AuthContext';
import styles from './Navbar.module.css';
import { FaBolt, FaSearch, FaBars, FaTimes, FaUser, FaShoppingBag, FaPercent, FaBlog } from 'react-icons/fa';
import cashHerosLogo from '../assets/cashheros-logo.png';

/**
 * Enhanced Navbar component with improved responsive design and user experience
 */
export const Navbar = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSearchExpanded, setIsSearchExpanded] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const { user, logout } = useContext(AuthContext);
  const navigate = useNavigate();
  const location = useLocation();
  const dropdownRef = useRef(null);
  const searchInputRef = useRef(null);

  // Handle scroll effect for sticky navbar
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 50) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Close mobile menu when route changes
  useEffect(() => {
    setIsMobileMenuOpen(false);
  }, [location.pathname]);

  // Handle search form submission
  const handleSearch = (e) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      navigate(`/stores?search=${searchTerm}`);
      setSearchTerm('');
      setIsSearchExpanded(false);
    }
  };

  // Toggle search input expansion on mobile
  const toggleSearchExpand = () => {
    setIsSearchExpanded(!isSearchExpanded);
    // Focus the input when expanded
    if (!isSearchExpanded) {
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 100);
    }
  };

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Handle user logout
  const handleLogout = () => {
    logout();
    setIsDropdownOpen(false);
    navigate('/');
  };

  // Toggle user dropdown menu
  const toggleDropdown = () => {
    setIsDropdownOpen(!isDropdownOpen);
  };

  // Toggle mobile menu
  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  // Determine if a nav link is active
  const isActive = (path) => {
    if (path === '/' && location.pathname === '/') return true;
    if (path !== '/' && location.pathname.startsWith(path)) return true;
    return false;
  };

  return (
    <nav className={`${styles.navbar} ${isScrolled ? styles.stickyNavbar : ''}`}>
      <div className={styles.navbarItems}>
        {/* Logo */}
        <div className={styles.logoContainer}>
          <Link to="/" className={styles.logoLink}>
            <img src={cashHerosLogo} alt="CashHeros Logo" className={styles.logo} />
          </Link>

          {/* Mobile menu toggle button */}
          <button 
            className={styles.mobileMenuToggle} 
            onClick={toggleMobileMenu}
            aria-label="Toggle navigation menu"
          >
            {isMobileMenuOpen ? <FaTimes /> : <FaBars />}
          </button>
        </div>

        {/* Navigation Links - Desktop and Mobile */}
        <div className={`${styles.navbarLinksContainer} ${isMobileMenuOpen ? styles.mobileMenuOpen : ''}`}>
          <div className={styles.navbarLinks}>
            <Link to="/" className={isActive('/') ? styles.activeLink : ''}>
              <span className={styles.linkIcon}><FaShoppingBag /></span>
              <span className={styles.linkText}>Deals</span>
            </Link>
            <Link to="/stores" className={isActive('/stores') ? styles.activeLink : ''}>
              <span className={styles.linkIcon}><FaShoppingBag /></span>
              <span className={styles.linkText}>Stores</span>
            </Link>
            <Link to="/cashback" className={isActive('/cashback') ? styles.activeLink : ''}>
              <span className={styles.linkIcon}><FaPercent /></span>
              <span className={styles.linkText}>Cash Back</span>
            </Link>
            <Link to="/blog" className={isActive('/blog') ? styles.activeLink : ''}>
              <span className={styles.linkIcon}><FaBlog /></span>
              <span className={styles.linkText}>Blog</span>
            </Link>
          </div>

          {/* Mobile Search Form */}
          <div className={styles.mobileSearchContainer}>
            <form onSubmit={handleSearch} className={styles.mobileSearchForm}>
              <input
                type="text"
                placeholder="Search stores, deals..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className={styles.mobileSearchInput}
              />
              <button type="submit" className={styles.mobileSearchButton}>
                <FaSearch />
              </button>
            </form>
          </div>

          {/* Mobile Auth Buttons */}
          {!user && (
            <div className={styles.mobileAuthButtons}>
              <Link to="/login" className={styles.mobileAuthLink}>
                <button className={styles.mobileNavbarBtnSign}>Sign In</button>
              </Link>
              <Link to="/signup" className={styles.mobileAuthLink}>
                <button className={styles.mobileNavbarBtnSign}>Sign Up</button>
              </Link>
            </div>
          )}
        </div>

        {/* Desktop Search Form */}
        <div className={`${styles.searchContainer} ${isSearchExpanded ? styles.expanded : ''}`}>
          <button 
            className={styles.searchToggle} 
            onClick={toggleSearchExpand}
            aria-label="Toggle search"
          >
            <FaSearch />
          </button>
          <form onSubmit={handleSearch} className={styles.searchForm}>
            <input
              ref={searchInputRef}
              type="text"
              placeholder="Search stores, deals..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className={styles.searchInput}
            />
            <button type="submit" className={styles.searchButton}>
              <FaSearch />
            </button>
          </form>
        </div>

        {/* User Section - Desktop */}
        {user ? (
          <div className={styles.userSection}>
            <div className={styles.authenticatedUser} ref={dropdownRef}>
              <button onClick={toggleDropdown} className={styles.userButton}>
                <FaUser className={styles.userIcon} />
                <span className={styles.userEmail}>{user.email}</span>
                <span className={styles.dropdownArrow}>▼</span>
              </button>
              {isDropdownOpen && (
                <div className={styles.dropdownMenu}>
                  <div className={styles.dropdownHeader}>
                    <span className={styles.welcomeText}>Welcome!</span>
                    <span className={styles.userEmailSmall}>{user.email}</span>
                  </div>
                  <Link to="/offers" className={styles.dropdownItem}>
                    My Offers <span className={styles.newBadge}>NEW</span>
                  </Link>
                  <Link to="/rewards" className={styles.dropdownItem}>
                    My Rewards <span className={styles.newBadge}>NEW</span>
                  </Link>
                  <Link to="/account" className={styles.dropdownItem}>
                    My Account
                  </Link>
                  <button onClick={handleLogout} className={styles.dropdownItem}>
                    Log Out
                  </button>
                </div>
              )}
              <button className={styles.balanceButton} onClick={() => navigate('/rewards')}>
                <FaBolt className={styles.lightningIcon} /> ${user.balance || '0.00'}
              </button>
            </div>
          </div>
        ) : (
          <div className={styles.authButtons}>
            <Link to="/login">
              <button className={styles.navbarBtnSign}>Sign In</button>
            </Link>
            <Link to="/signup">
              <button className={styles.navbarBtnSignUp}>Sign Up</button>
            </Link>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
